function page_end(): void { ?><footer class="page-footer"><span>© <?= date('Y') ?> YBT Management Software</span><span><?= icon('shield-check') ?> A clearer picture. A better business.</span><span>Version 1.0 · Local workspace</span></footer></main></div><dialog id="confirm-dialog"><form method="dialog"><h2>Confirm this action</h2><p id="confirm-message"></p><div class="form-actions"><button value="cancel" class="btn">Cancel</button><button value="confirm" class="btn danger">Confirm</button></div></form></dialog></body></html><?php }
function field(string $key,array $definition,mixed $value=''): void { [$label,$type]=$definition; $required=$definition[2]??false; echo '<label class="field '.($type==='textarea'?'full':'').'"><span>'.e($label).($required?' <b>*</b>':'').'</span>'; if(is_array($type)||in_array($type,['users','customers'],true)){ echo '<select name="'.e($key).'" '.($required?'required':'').'>'; if(in_array($type,['users','customers'],true)){echo '<option value="">Unassigned</option>'; $table=$type; foreach(rows("SELECT id,name FROM $table WHERE business_id=? ORDER BY name",[bid()]) as $r) echo '<option value="'.$r['id'].'" '.((string)$value===(string)$r['id']?'selected':'').'>'.e($r['name']).'</option>'; }else foreach($type as $option) echo '<option '.($value===$option?'selected':'').'>'.e($option).'</option>'; echo '</select>'; }elseif($type==='textarea') echo '<textarea name="'.e($key).'" rows="3" maxlength="4000">'.e($value).'</textarea>'; else echo '<input name="'.e($key).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required':'').' '.($type==='number'?'min="0" max="99999999" step="0.01"':'maxlength="200"').'>'; echo '</label>'; }
function error_notice(string $error): void { if($error!=='') echo '<div class="notice error" role="alert">'.icon('help-circle').e($error).'</div>'; }
